<!doctype html><html lang="es"><head><meta charset="utf-8"><title>Comprobante #{{ $venta->id_venta }}</title><style>body{font:14px Arial;color:#231a15;margin:20px}.receipt{width:360px;margin:auto}.center{text-align:center}table{width:100%;border-collapse:collapse;margin:15px 0}td,th{padding:5px 0;border-bottom:1px dashed #aaa;text-align:left}.right{text-align:right}.total{font-size:20px;font-weight:bold}@media print{.no-print{display:none}}</style></head><body><div class="receipt"><div class="center"><h2>Salteñería Cupesí</h2><p>Comprobante de venta</p></div><p>Sucursal: {{ $venta->sucursal?->nombre }}<br>Número: #{{ $venta->id_venta }}<br>Fecha: {{ $venta->fecha_venta?->format('d/m/Y H:i') }}<br>Cajero: {{ $venta->usuario?->nombre_usuario }}</p><table><tr><th>Producto</th><th>Cant.</th><th class="right">Importe</th></tr>@foreach($venta->detalles as $d)<tr><td>{{ $d->producto?->nombre }}</td><td>{{ $d->cantidad }}</td><td class="right">Bs {{ number_format($d->subtotal,2,',','.') }}</td></tr>@endforeach</table><p class="right total">Total: Bs {{ number_format($venta->total,2,',','.') }}</p><p><strong>Métodos de pago</strong><br>@foreach($venta->pagos as $p){{ $p->metodoPago?->nombre }}: Bs {{ number_format($p->importe,2,',','.') }}<br>@endforeach</p><div class="center no-print"><button onclick="window.print()">Imprimir</button></div></div></body></html>
